#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>
#include <vector>

struct Registro {
    std::string codigo;
    int cantidad;
    double medida;
};

std::string componer_fila(const Registro& registro) {
    std::ostringstream texto;
    texto << "[" << std::left << std::setfill(' ') << std::setw(6) << registro.codigo
        << "]|[" << std::right << std::setw(4) << std::dec << registro.cantidad
        << "]|[" << std::fixed << std::setprecision(2) << registro.medida << "]";
    return texto.str();
}

std::string componer_informe(const std::vector<Registro>& registros) {
    std::ostringstream texto;
    int total = 0;
    double suma_medidas = 0.0;
    for (const auto& registro : registros) {
        texto << componer_fila(registro) << "\n";
        total += registro.cantidad;
        suma_medidas += registro.medida;
    }
    texto << "Total:" << std::dec << total << ";";
    if (registros.empty()) {
        texto << "Sans mesures";
    } else {
        double media = suma_medidas / static_cast<double>(registros.size());
        texto << "Moyenne:" << std::fixed << std::setprecision(2) << media;
    }
    return texto.str();
}

int main() {
    const std::vector<Registro> registros{{"A", 5, 4.3125}, {"Salle", 7, 6.9375}, {"Couloir", 0, 0.0}};
    std::cout << componer_informe(registros);
    return 0;
}

